-- Imported verbatim from Account Book in MRPST 2026.xlsx (1 December rows).
with import_rows as (select * from jsonb_to_recordset($json$[{"reference_no":"XLSX-2026-December-income-15","entry_date":"2026-12-31","description":"December import 1 (Excel import)","debit_code":"1010","credit_code":"4010","amount":57483}]$json$) as x(reference_no text,entry_date date,description text,debit_code text,credit_code text,amount numeric)), configuration as (select (select id from public.finance_funds where code='GENERAL') as fund_id,'54f73659-2cc1-4ddd-822f-526c799af37f'::uuid as actor_id), mapped as (select r.*,da.id debit_account_id,ca.id credit_account_id from import_rows r join public.finance_accounts da on da.code=r.debit_code join public.finance_accounts ca on ca.code=r.credit_code), created as (insert into public.journal_entries(entry_date,description,reference_no,fund_id,status,created_by,submitted_by,submitted_at,approved_by,approved_at,posted_by,posted_at) select m.entry_date,m.description,m.reference_no,c.fund_id,'draft',c.actor_id,c.actor_id,m.entry_date::timestamptz,c.actor_id,m.entry_date::timestamptz,c.actor_id,m.entry_date::timestamptz from mapped m cross join configuration c where not exists(select 1 from public.journal_entries e where e.reference_no=m.reference_no) returning id,reference_no), lines as (select e.id,1 line_no,m.description,m.debit_account_id account_id,m.amount debit,0::numeric credit from created e join mapped m using(reference_no) union all select e.id,2,m.description,m.credit_account_id,m.amount*0,m.amount from created e join mapped m using(reference_no)), inserted_lines as (insert into public.journal_lines(entry_id,line_no,description,account_id,debit,credit) select id,line_no,description,account_id,debit,credit from lines returning entry_id) update public.journal_entries set status='posted' where id in(select entry_id from inserted_lines);
